def choose_move(observation):
    # Defensive defaults
    x = observation.get('position', {}).get('x', 0)
    y = observation.get('position', {}).get('y', 0)

    # Initialize move to stay unless tasks dictate otherwise
    dx = 0
    dy = 0

    # Resource collection: move toward nearest resource if present
    resources = observation.get('resources') or observation.get('resource_positions') or []
    if isinstance(resources, list) and resources:
        # Find nearest resource by Manhattan distance
        best = None
        best_dist = 10**9
        for r in resources:
            rx = r.get('x') if isinstance(r, dict) else None
            ry = r.get('y') if isinstance(r, dict) else None
            if rx is None or ry is None:
                continue
            dist = abs(rx - x) + abs(ry - y)
            if dist < best_dist:
                best_dist = dist
                best = (rx, ry)
        if best is not None and best_dist > 0:
            tx, ty = best
            if tx > x:
                dx = 1
            elif tx < x:
                dx = -1
            if ty > y:
                dy = 1
            elif ty < y:
                dy = -1
            # If already aligned on one axis, ensure movement toward it
            if dx != 0 and dy != 0:
                pass

    # If no resources or to diversify behavior, pursue a basic heuristic:
    # Pursuit/evade: move away from closest "enemy" if present; otherwise patrol center-ish
    enemies = observation.get('enemies') or observation.get('pursuers') or []
    if isinstance(enemies, list) and enemies:
        best_enemy = None
        best_dist = 10**9
        for e in enemies:
            ex = e.get('x') if isinstance(e, dict) else None
            ey = e.get('y') if isinstance(e, dict) else None
            if ex is None or ey is None:
                continue
            dist = abs(ex - x) + abs(ey - y)
            if dist < best_dist:
                best_dist = dist
                best_enemy = (ex, ey)
        if best_enemy is not None:
            ex, ey = best_enemy
            # Move away from enemy if possible
            if ex > x:
                dx = -1 if dx == 0 else dx
            elif ex < x:
                dx = 1 if dx == 0 else dx
            if ey > y:
                dy = -1 if dy == 0 else dy
            elif ey < y:
                dy = 1 if dy == 0 else dy

    # Territory control heuristic: if under-defended or near border centers, adjust
    # Try to move toward center (0,0) by default when no other directive
    if dx == 0 and dy == 0:
        cx, cy = observation.get('center', {}).get('x', 0), observation.get('center', {}).get('y', 0)
        if cx is None or cy is None:
            cx, cy = 0, 0
        if cx > x:
            dx = 1
        elif cx < x:
            dx = -1
        if cy > y:
            dy = 1
        elif cy < y:
            dy = -1

    # Ensure moves are within -1..1
    if dx not in (-1, 0, 1):
        dx = 0
    if dy not in (-1, 0, 1):
        dy = 0

    return [dx, dy]

